update public.sarpras_katalog set spesifikasi='{"nama_form": "Kendaraan pick-up 4WD (4x4)", "default": null, "variants": {"Mahindra Scorpio Single Cab S6": "Type: Mahindra Scorpio Pikup Single Cab 4x4 S6\n[Overall Dimension]\nOverall Length (mm): 5160\nOverall Width (mm): 1822\nOverall Height (mm): 1805\nWheelbase (mm): 3034\nGround Clearance (mm): 230\n[Tray Dimension]\nLength x Width x Height in mm - Inner: 2300x1555x550\n[Mesin & Performa]\nEngine & Emission standard: 2.2L mHawk Diesel 4 cylinder Turbocharged Commonrail Direct Injection (Euro4 Emission)\nEngine Capacity: 2179 cc\nFuel type: Diesel\nTransmission: Manual Transmission – 6 speeds\nPower: 140 HP @3750 rpm\nTorque: 320 Nm @1500-2800 rpm\nTraction: 4x4 – Shift on the fly\nTyres: 245/75 R16\nWheels: 6.5J16 (Steel wheel with cap)\n[Berat & Kapasitas]\nGVW (kg): 3150 kg\nKERB (kg): 2055\nPay Load (kg): 1095\nFuel tank capacity (lt): 80L\nTowing Capacity: 2.5 Ton", "Tata Yodha Single Cabin": "Type: Tata Yodha Single Cab 4x4\n[Engine]\nType: Common rail direct injection Turbocharged Intercooled diesel engine\nCapacity: 2.179 cc\nPower: 100 PS at 3.750 rpm\nTorque: 250 Nm at 1.000 – 2.500 rpm\nFuel Tank Capacity: 52L\n[Clutch & Transmission]\nClutch: Single Plate Dry Friction Diaphragm Conventional\nGearbox: 5 Speed Manual Transmission with Synchromesh on all Gears\nSteering: Power Steering\n[Suspension]\nFront Suspension: Semielliptical type\nRear Suspension: Semielliptical type\nAnti Roll Bar: At Front\n[Weights]\nGross Vehicle Weight: 2.990 kg\nKerb Weight: 1.780 kg\nPayload: 1.210 kg\n[Dimensions]\nOverall Height (mm): 1.810\nOverall Length (mm): 5.025\nOverall Width (mm): 1.860\n[Tyres]\nTyres: 215/75 R16"}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kdn_pickup_mahindra_scorpio_single_cab_s6.jpg", "./assets/img/sarpras/kdn_pickup_mahindra_scorpio_single_cab_s6_belakang.jpg", "./assets/img/sarpras/kdn_pickup_mahindra_scorpio_single_cab_s6_samping.jpg", "./assets/img/sarpras/kdn_pickup_tata_yodha_single_cabin.jpg", "./assets/img/sarpras/kdn_pickup_tata_yodha_single_cabin_belakang.jpg", "./assets/img/sarpras/kdn_pickup_tata_yodha_single_cabin_samping.jpg"]}'::jsonb,daftar_tipe='["Mahindra Scorpio Single Cab S6", "Tata Yodha Single Cabin"]'::jsonb where item_id='KDN_PICKUP';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Motor bak roda 3", "default": null, "variants": {"Power Ace Max Pro": "Type: Power Ace Max Pro\n[Mesin]\nTipe Mesin: 4 Langkah SOHC\nTipe Pendingin: Water Cooler Radiator\nDiameter x Langkah: 63.5 x 62.2 mm\nKopling: Manual Multiple Wet Clutch\nPengoperasian Transmisi: N-1-2-3-4-5 +R\nSistem Pengapian: CDI\n[Rangka & Kaki-Kaki]\nTipe Suspensi Depan: Teleskopik\nTipe Suspensi Belakang: Pegas daun+pegas spiral\nRem Depan: Tromol\nRem Belakang: Tromol R/L\nUkuran Ban: 450-12\n[Dimensi & Berat]\nPanjang x Lebar x Tinggi: 3350 x 1200 x 1350 mm\nBerat Kosong: 370 Kg\n[Kapasitas]\nKapasitas Tangki: 14 Liter\nKapasitas Silinder: 200 cc\nKapasitas Minyak Pelumas: 1.5 Liter\nDaya Angkut: 500 Kg\n[Kelistrikan]\nBaterai: 12V\n[Spesifikasi Carrier]\nPanjang x Lebar x Tinggi: 1800 x 1200 x 550 mm\nMaterial: Frame Baja dan Plat Bordes", "HTM 200 DP 2.0": "Type: HTM 200 DP 2.0\n[Dimensi]\nKeseluruhan (PxLxT): 3680 x 1310 x 1535 mm\nBak (PxLxT): 2000 x 1250 x 560 mm\nDaya Angkut: 636 Kg\nJarak Sumbu Roda: 2450 mm\nJarak Terendah: 180 mm\nBerat Kosong: 464 Kg\nUkuran Ban Depan: 4.50 –R12\nUkuran Ban Belakang: 4.50 - R12\n[Mesin]\nTipe: HM 200 M/T\nTipe Mesin: 4 Langkah OHV, Water cooler\nDiameter x Langkah: 63.5 x 62.5\nVolume Silinder: 200 cc\nDaya Maksimum: 11.5 kW/7500 rpm\nTorsi Maksimum: 15 Nm/7000 rpm\nPerbandingan Kompresi: 10:1\nSistem Starter: Elektrik dan Pedal\nSistem Pengapian: CDI – AC\nKopling: Tipe Basah, manual dengan tuas kopling\nGigi Transmisi: 5 Gigi kecepatan dan mundur\nPola Pengoperan Gigi: 1-N-2-3-4-5\nSistem Bahan Bakar: Karburator\nBahan Bakar: Bensin\nBusi: TORCH 08 RC TM\nBattery: 12V – 10Ah\n[Rangka]\nTipe: Rangka Kotak\nSuspensi Depan: Teleskopik\nSuspensi Belakang: Pegas Daun dan Peredam Hidrolik\nGardan: Double Power\nRem Depan: Tromol\nRem Belakang: Tromol.R-L\nRem Tangan: Ada\n[Kapasitas]\nTangki Bahan Bakar: 15L\nOli Mesin: 1L\nOli Reverse Gear: 100 mL\nOli Gardan: 600 mL", "Kaisar Triseda K 200cc": "Type: Kaisar Triseda K 200cc\n[Mesin Penggerak]\nModel Mesin (Penggerak Katup): SOHC\nLetak Motor Penggerak: FR (Front Engine – Rear Wheel Drive)\nSistem Pembakaran (Sistem Injeksi): CDI/Transistor\nJumlah Silinder dan Konfigurasi Silinder: Tunggal\nDiameter x Langkah Torak (mm x mm): 63,5x62,2\nDaya Maksimum (Kw / Rpm : HP/Rpm): 10 KW/7500 Rpm\nTorsi Maksimum: 14,2 Nm/6000 Rpm\nIdle Speed (Rpm): 1200\nVolume Silinder (cc): 197cc\nKecepatan Maksimum: 60 Km/Jam\n[Sistem Bahan Bakar]\nJenis Bahan Bakar: Bensin\nSistem Pemberian Bahan Bakar (Supply): Karburator\nKapasitas Tanki Bahan Bakar (Liter): 18 Liter\n[Penerus Daya (Transmisi/Kopling)]\nTipe Transmisi: Manual\nSistem Kendali Transmisi: Kendali Kaki\nPerbandingan Gigi - Gigi 1: 15.223\nPerbandingan Gigi - Gigi 2: 9.345\nPerbandingan Gigi - Gigi 3: 7.195\nPerbandingan Gigi - Gigi 4: 6.105\nPerbandingan Gigi - Gigi 5: 4.71\nPerbandingan Gigi - Gigi Mundur: 1.154\nPerbandingan Gigi - Gigi Akhir: 3.5\nTipe Kopling: Multi Wet Clutch\n[Sistem Pengereman]\nRem Utama - Pengendalian: Mekanis\nRem Utama - Tipe Rem Depan: Tromol\nRem Utama - Tipe Rem Belakang: Tromol\nRem Parkir - Pengoperasian: Tuas\nRem Parkir - Tipe: Mekanis\nRem Parkir - Bekerja Pada: Roda Belakang", "APPKTM Mesin 200cc": "Type: APPKTM Mesin 200cc\n[Dimensi]\nBak (PxLxT): 1850x1350x750 mm\nDaya Angkut: 636 Kg\nUkuran Ban Depan: 4.50 - R12\nUkuran Ban Belakang: 4.50 - R12\n[Mesin]\nTipe Mesin: 4 Langkah OHV, Water Cooler\nVolume Silinder: 200 cc\nDaya Maksimum: 11,5 kW / 7500 rpm\nTorsi Maksimum: 15 Nm / 7000 rpm\nSistem Starter: Elektrik dan Pedal\nSistem Pengapian: CDI – AC\nGigi Transmisi: 5 Gigi kecepatan dan mundur\nPola Pengoperasian Gigi: 1-N-2-3-4-5\nBahan Bakar: Bensin\n[Rangka]\nSuspensi Depan: Teleskopik\nSuspensi Belakang: Pegas Daun dan Peredam Hidrolik\nRem Depan: Tromol\nRem Belakang: Tromol.R-L\nRem Tangan: Ada\n[Kapasitas]\nTangki Bahan Bakar: 15 L\nOli Mesin: 1 L\nOli Reverse Gear: 100 mL\nOli Gardan: 600 mL\nHidrolik: Ada"