update public.sarpras_katalog set spesifikasi='{"nama_form": "POS (Point of Sales)", "default": "OS: Android 11\nProcessor: Quad-core, 2.0GHz\nMemory: 2GB RAM; 32GB ROM\nMain Screen: 15.6\" touch screen (1366*768 resolution)\nSub-Screen: 10.1\" display screen (1280*800 resolution)\nNFC: Supports mainstream high-frequency cards\nBluetooth: Supports BT 3.0/4.0\nLAN: 10M/100M adaptive\nWiFi: Supports dual-band WiFi (2.4GHz & 5GHz)\nSpeaker: 2W\nPorts: 4×USB, 1×RJ11, 1×RJ12, 1×RJ45, 1×HDMI, 1×Headphone jack, 1×DC port\nAdapter: 24V/1.5A\nOperating temperature: -10℃ ~ 50℃\nOperating humidity: 30% ~ 80% (non-condensing)\nStorage temperature: -20℃ ~ 60℃\nStorage humidity: 10% ~ 90% (non-condensing)", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_pos.jpg", "./assets/img/sarpras/ops_kasir_pos_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_POS';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Cash Drawer", "default": "Tipe: Cash Drawer BQ330DK\nLock & Emergency Switch: Three-position lock; Emergency switch at the bottom\nSlots Configuration: 4 bill slots, 4 coin slots (all slots adjustable); Removable coin box; No check slot\nMaterial: Metal money clip; Galvanized base plate; Metal panel\nInterface: RJ11 (default), RJ12 with microswitch, MICRO, USB (optional)\nColor: Black\nVoltage: 12V\nWeight: Net weight: 4.1 kg; Gross weight: 4.5 kg\nCash drawer size: 335W × 360L × (90+10)H mm\nPackaging size: 415W × 405L × 145H mm\nOptional Accessory: Orange decorative strip", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_cash_drawer.jpg", "./assets/img/sarpras/ops_kasir_cash_drawer_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_CASH_DRAWER';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Gun Scanner", "default": "Tipe: Gun Scanner S22 V2\nProcessor: 32bit secure processor\nAcquisition Method: Image-based\nCamera: 800*600 resolution, 500,000-pixel CMOS\nView Angle: 48° (Horizontal) × 30° (Vertical)\nAcquisition Speed: 1/30 second\nRecognition Precision: 2D: ≥8mil; 1D: ≥3mil\nWorking Voltage: DC 5V ±10%\nWorking Current: Working: 150mA; Standby: 25mA\nCommunication Interface: USB-HID (default)\nSupported Code Types 1D: UPC-A, UPC-E, EAN-8, EAN-13, Code 128, GS1-128, ISBT-128, Code 39, Code 93, Code 11, Interleaved 2 of 5, Industrial 2 of 5, Matrix 2 of 5, Standard 2 of 5, Codabar, MSI/MSI-Plessey, GS1-DataBar/RSS\nSupported Code Types 2D: PDF417, QRCode, Aztec Code, DM(DataMatrix), MaxiCode, Han Xin Code (supports mobile screen reading)", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_gun_scanner.jpg", "./assets/img/sarpras/ops_kasir_gun_scanner_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_GUN_SCANNER';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Finger Print", "default": "Tipe: Fingerprint AGF300\n[Electrical Parameters]\nCommunication Interface: USB1.1/2.0\nSupply Voltage: 5V (typical), range: 4.2V-5.5V\nWorking Current: 120mA (typical)\n[Performance Index]\nSensor Type: Optical\nAcquisition Method: Press-type\nHousing Dimensions: 67.6×36×15.1mm\nAcquisition Window: 24.0 × 26.0mm\nImage Size: 400*500pixels\nImage Resolution: 500DPI\nDistortion: ≤1%\nGrayscale Level: 8-bit, 256 levels\nGrayscale Dynamic Range: ≥150\nAcquisition Speed: ≥15 frames/s\nMatching Method: 1:1 Comparison; 1:N Search\nSearch Time: <0.1s (1:1); <1s (1:N, 1000 templates)\nFalse Acceptance Rate (FAR): <0.0001%\nFalse Rejection Rate (FRR): <0.5%\nESD Protection Level: Contact discharge: ±8KV; Air discharge: ±15KV\nSystem Support: Windows, Android", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_fingerprint.jpg", "./assets/img/sarpras/ops_kasir_fingerprint_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_FINGERPRINT';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Printer Receipt", "default": "Tipe: Printer Receipt FH0P58A - 58mm\nPrint Speed: 90mm/s\nPrinting Broadband: 57.5mm±0.5mm\nPaper Bin Size: 58 × φ60mm (MAX)\nPrint Head Lifespan: 150KM\nPaper Cutting Method: Tear the paper by hand\nPower Supply: European standard power supply\nPort: USB + cash box interface", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_printer_receipt.jpg", "./assets/img/sarpras/ops_kasir_printer_receipt_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_PRINTER_RECEIPT';
