update public.sarpras_katalog set spesifikasi='{"nama_form": "EDC", "default": "Tipe: EDC K9\nOS: Android 13\nCPU: High Performance Quad-core CPU\nMemory: 2GB RAM + 16GB ROM\nDisplay: 5.5\" HD, 1280x720, Multiple-point Touchscreen\nCamera: 2MP Front Camera, 5MP Rear Camera With A Flashlamp\nCommunication: 2G/3G/4G, WIFI 802.11 a/b/g/n, Bluetooth 5.0, Ethernet\nIC Card Reader: ISO 7816, EMV Standard\nMagnetic Card Reader: Support 1/2/3 Track And Bi-directional Swipe\nContactless Card Reader: ISO 14443 A&B, Mifare Card Standard\nGPS: GPS/Beidou/Glonass/A-GPS/LBS\nCard Slot: SIM x1 + PSAM x2 (PSAM2 slot can be used as SIM2), Maximum 128G TF Card\nPorts: Type C x 1, Support OTG\nPrinter: Thermal Printer, 58/40mm Paper Roll, Printing Speed 18 Lines/s\nBattery: 2600mAh, 7.2v, 18.72Wh", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_edc.jpg", "./assets/img/sarpras/ops_kasir_edc_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_EDC';